package com.example.lms.controller;
import com.example.lms.dto.*; import com.example.lms.service.StudentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.List;
@RestController @RequestMapping("/api/students") public class StudentController {private final StudentService service; public StudentController(StudentService s){service=s;} @GetMapping public List<StudentResponse> list(){return service.list();} @GetMapping("/{id}") public StudentResponse get(@PathVariable Long id){return service.get(id);} @PostMapping public ResponseEntity<StudentResponse> create(@Valid @RequestBody StudentRequest r){var p=service.create(r);return ResponseEntity.created(URI.create("/api/students/"+p.id())).body(p);}@PutMapping("/{id}") public StudentResponse update(@PathVariable Long id,@Valid @RequestBody StudentUpdateRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
